INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_03','V1001','阮明',3,'我突然发高烧，还一直拉肚子，浑身软得不行，站都站不稳。','wǒ tū rán fā gāo shāo ， hái yì zhí lā dù zi ， hún shēn ruǎn dé bù xíng ， zhàn dōu zhàn bù wěn 。','Tớ tự nhiên sốt cao, lại còn bị tiêu chảy liên tục, người mềm nhũn cả ra, đứng cũng không vững.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_04','V1001','林晓',4,'我的天，这么严重！校医室早就关门了，晚上没有医生值班，我陪你去校外的24小时急诊吧！','wǒ de tiān ， zhè me yán zhòng ！ xiào yī shì zǎo jiù guān mén le ， wǎn shàng méi yǒu yī shēng zhí bān ， wǒ péi nǐ qù xiào wài de 24 xiǎo shí jí zhěn ba ！','Trời ơi, nặng vậy sao! Phòng y tế trường đóng cửa từ lâu rồi, ban đêm không có bác sĩ trực, để em đưa anh ra phòng cấp cứu 24 giờ ngoài trường nhé!','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_05','V1001','阮明',5,'可以吗？可是我身上没多少现金，手机支付也不太方便……','kě yǐ ma ？ kě shì wǒ shēn shàng méi duō shǎo xiàn jīn ， shǒu jī zhī fù yě bù tài fāng biàn ……','Được không em? Nhưng mà tớ không mang nhiều tiền mặt, thanh toán qua điện thoại cũng không tiện lắm...',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_06','V1001','林晓',6,'没事没事，钱的事你别管，我先帮你垫付，你身体要紧，先去看病！','méi shì méi shì ， qián de shì nǐ bié guǎn ， wǒ xiān bāng nǐ diàn fù ， nǐ shēn tǐ yào jǐn ， xiān qù kàn bìng ！','Không sao không sao, chuyện tiền anh đừng lo, em ứng trước cho, sức khỏe quan trọng hơn, mình đi khám trước đã!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_07','V1001','阮明',7,'真的太谢谢你了……我现在站起来就头晕，得麻烦你扶我一下。','zhēn de tài xiè xiè nǐ le …… wǒ xiàn zài zhàn qǐ lái jiù tóu yūn ， dé má fán nǐ fú wǒ yī xià 。','Thật sự cảm ơn em nhiều lắm... giờ tớ đứng dậy là chóng mặt, phiền em đỡ tớ một chút.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1001_08','V1001','林晓',8,'别客气，赶紧披上厚外套，夜里风特别大，别再加重了，我们马上走。','bié kè qì ， gǎn jǐn pī shàng hòu wài tào ， yè lǐ fēng tè bié dà ， bié zài jiā zhòng le ， wǒ men mǎ shàng zǒu 。','Anh đừng khách sáo, mau khoác thêm áo khoác dày vào, đêm gió to lắm, đừng để bệnh nặng thêm, mình đi ngay thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1002','SKC1','宿舍水管爆裂积水，紧急联系后勤抢修止损',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1002','SIT1002','P1','suon_se','ban_chinh_thuc',NULL,'高校宿舍后勤维修分时段报修，突发漏水这类险情可直接拨打应急专线，不用走线上预约流程。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_01','V1002','阮明',1,'张师傅！麻烦您快来一下，我是3栋402的学生，我们宿舍出事了！','zhāng shī fù ！ má fán nín kuài lái yī xià ， wǒ shì 3 dòng 402 de xué shēng ， wǒ men sù shè chū shì le ！','Chú Trương ơi! Phiền chú đến gấp giúp cháu, cháu là sinh viên phòng 402 tòa 3, phòng ký túc xá của bọn cháu gặp sự cố rồi ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_02','V1002','张师傅',2,'同学别急，慢慢说，怎么了？是漏水还是断电了？','tóng xué bié jí ， màn màn shuō ， zěn me le ？ shì lòu shuǐ hái shì duàn diàn le ？','Em đừng vội, từ từ nói, chuyện gì vậy? Bị rò nước hay là mất điện?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_03','V1002','阮明',3,'卫生间的水管突然爆了！水一直往外喷，地上全是积水，马上就要漫到书桌和床铺了！','wèi shēng jiān de shuǐ guǎn tū rán bào le ！ shuǐ yì zhí wǎng wài pēn ， dì shàng quán shì jī shuǐ ， mǎ shàng jiù yào màn dào shū zhuō hé chuáng pù le ！','Ống nước trong nhà vệ sinh tự nhiên bị vỡ ạ! Nước cứ phun ra liên tục, sàn nhà ngập hết nước rồi, sắp tràn tới bàn học với giường ngủ luôn!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_04','V1002','张师傅',4,'我知道了，你先试着把卫生间总水阀关掉，先止水，别让水一直流。','wǒ zhī dào le ， nǐ xiān shì zhe bǎ wèi shēng jiān zǒng shuǐ fá guān diào ， xiān zhǐ shuǐ ， bié ràng shuǐ yì zhí liú 。','Chú biết rồi, em thử khóa van nước tổng ở nhà vệ sinh lại trước đã, chặn nước lại, đừng để nước chảy mãi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_05','V1002','阮明',5,'我试过了师傅！总水阀拧不动，彻底关不上，积水越积越多，再拖地板就要泡坏了！','wǒ shì guò le shī fù ！ zǒng shuǐ fá níng bù dòng ， chè dǐ guān bù shàng ， jī shuǐ yuè jī yuè duō ， zài tuō dì bǎn jiù yào pào huài le ！','Cháu thử rồi chú ơi! Van nước tổng vặn không được, không thể khóa lại được, nước cứ dâng lên mãi, để lâu nữa là sàn nhà ngâm nước hỏng mất!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_06','V1002','张师傅',6,'行，我立马带工具上楼，十分钟之内到。你先用拖把、脸盆先舀水，尽量控一下积水。','xíng ， wǒ lì mǎ dài gōng jù shàng lóu ， shí fēn zhōng zhī nèi dào 。 nǐ xiān yòng tuō bǎ 、 liǎn pén xiān yǎo shuǐ ， jǐn liàng kòng yī xià jī shuǐ 。','Được, chú mang dụng cụ lên ngay đây, mười phút nữa là tới. Em dùng cây lau nhà với chậu múc bớt nước ra, cố gắng khống chế lượng nước đọng lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_07','V1002','阮明',7,'好好！我现在马上清理，麻烦您快点过来！','hǎo hǎo ！ wǒ xiàn zài mǎ shàng qīng lǐ ， má fán nín kuài diǎn guò lái ！','Vâng vâng! Cháu dọn ngay bây giờ, phiền chú đến nhanh giúp cháu với ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1002_08','V1002','张师傅',8,'放心，我已经出发了，到楼下给你打电话。','fàng xīn ， wǒ yǐ jīng chū fā le ， dào lóu xià gěi nǐ dǎ diàn huà 。','Yên tâm đi, chú xuất phát rồi, xuống tới tầng dưới chú gọi điện cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1003','SKC1','就餐食物严重过敏无抗过敏药，同学送医急救',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1003','SIT1003','P1','twist','tuy_y',NULL,'国内医院急诊可先救治后补登记证件，留学生就诊出示居留许可即可登记。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_01','V1003','阮明',1,'小雨……我不对劲，身上全是红疹子，呼吸也有点困难，好像过敏了。','xiǎo yǔ …… wǒ bú duì jìn ， shēn shàng quán shì hóng zhěn zi ， hū xī yě yǒu diǎn kùn nán ， hǎo xiàng guò mǐn le 。','Tiểu Vũ... tớ thấy không ổn, người nổi đầy mẩn đỏ, thở cũng hơi khó, hình như bị dị ứng rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_02','V1003','陈雨',2,'啊？怎么突然过敏了？你中午吃什么了？宿舍有没有过敏药先吃一点？','a ？ zěn me tū rán guò mǐn le ？ nǐ zhōng wǔ chī shén me le ？ sù shè yǒu méi yǒu guò mǐn yào xiān chī yì diǎn ？','Hả? Sao tự nhiên bị dị ứng vậy? Trưa nay anh ăn gì thế? Trong phòng có thuốc dị ứng không, uống tạm một ít đi?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_03','V1003','阮明',3,'中午在食堂吃的海鲜小炒……我宿舍没备药，现在喉咙越来越肿，好难受。','zhōng wǔ zài shí táng chī de hǎi xiān xiǎo chǎo …… wǒ sù shè méi bèi yào ， xiàn zài hóu lóng yuè lái yuè zhǒng ， hǎo nán shòu 。','Trưa nay tớ ăn món hải sản xào ở căng tin... phòng tớ không có sẵn thuốc, giờ cổ họng cứ sưng lên, khó chịu quá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_04','V1003','陈雨',4,'这绝对不行，不能硬扛！我现在骑车带你去校门口的医院急诊！','zhè jué duì bù xíng ， bù néng yìng káng ！ wǒ xiàn zài qí chē dài nǐ qù xiào mén kǒu de yī yuàn jí zhěn ！','Vậy không được đâu, không thể ráng chịu như vậy! Giờ để em chở anh đi cấp cứu ở bệnh viện gần cổng trường luôn!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_05','V1003','阮明',5,'可是我的证件都在宿舍柜子里，没带在身上，看病会不会不方便？','kě shì wǒ de zhèng jiàn dōu zài sù shè guì zi lǐ ， méi dài zài shēn shàng ， kàn bìng huì bú huì bù fāng biàn ？','Nhưng giấy tờ tùy thân của tớ để trong tủ ở phòng, không mang theo người, đi khám như vậy có bất tiện không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_06','V1003','陈雨',6,'先去看病，证件的事不急！我等下跟辅导员报备，回头帮你回宿舍拿。','xiān qù kàn bìng ， zhèng jiàn de shì bù jí ！ wǒ děng xià gēn fǔ dǎo yuán bào bèi ， huí tóu bāng nǐ huí sù shè ná 。','Đi khám trước đã, chuyện giấy tờ không gấp đâu! Lát nữa em báo với thầy cô chủ nhiệm, rồi quay về phòng lấy giúp anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_07','V1003','阮明',7,'太麻烦你了……我现在手脚发麻，有点站不住了。','tài má fán nǐ le …… wǒ xiàn zài shǒu jiǎo fā má ， yǒu diǎn zhàn bú zhù le 。','Phiền em quá... giờ tay chân tớ tê hết cả rồi, hơi đứng không vững nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1003_08','V1003','陈雨',8,'别说话，靠着我！我们现在立刻去医院！','bié shuō huà ， kào zhe wǒ ！ wǒ men xiàn zài lì kè qù yī yuàn ！','Anh đừng nói nữa, dựa vào em đi! Mình đi bệnh viện ngay bây giờ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1004','SKC1','宿舍大功率电器短路冒烟断电，联系宿管排查隐患',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1004','SIT1004','P1','suon_se','ban_chinh_thuc',NULL,'国内高校宿舍严禁大功率电煮锅、电暖锅等电器，违规使用引发电路故障需自行承担维修损失。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_01','V1004','阮明',1,'李阿姨，不好了！我是5栋206的阮明，我们宿舍插座冒烟，直接跳闸断电了！','lǐ ā yí ， bù hǎo le ！ wǒ shì 5 dòng 206 de ruǎn míng ， wǒ men sù shè chā zuò mào yān ， zhí jiē tiào zhá duàn diàn le ！','Cô Lý ơi, nguy rồi ạ! Cháu là Nguyễn Minh phòng 206 tòa 5, ổ cắm điện phòng cháu bốc khói, rồi nhảy cầu dao mất điện luôn ạ!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_02','V1004','李宿管',2,'冒烟了？你可千万别碰插座线路！有没有泼水或者拿手去摸电线？','mào yān le ？ nǐ kě qiān wàn bié pèng chā zuò xiàn lù ！ yǒu méi yǒu pō shuǐ huò zhě ná shǒu qù mō diàn xiàn ？','Bốc khói à? Em tuyệt đối đừng chạm vào ổ cắm hay dây điện nhé! Có tạt nước vào hay lấy tay sờ vào dây điện không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_03','V1004','阮明',3,'没有没有，我第一时间拔掉了所有电器插头，现在房间完全没电，不敢乱动。','méi yǒu méi yǒu ， wǒ dì yī shí jiān bá diào le suǒ yǒu diàn qì chā tóu ， xiàn zài fáng jiān wán quán méi diàn ， bù gǎn luàn dòng 。','Dạ không ạ, cháu rút hết tất cả phích cắm ngay lập tức, giờ phòng hoàn toàn mất điện, cháu không dám động vào gì cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_04','V1004','李宿管',4,'我问你，是用什么电器的时候出的事？是不是私用的电煮锅？','wǒ wèn nǐ ， shì yòng shén me diàn qì de shí hòu chū de shì ？ shì bú shì sī yòng de diàn zhǔ guō ？','Cô hỏi em, lúc xảy ra chuyện là đang dùng thiết bị điện gì vậy? Có phải là nồi điện tự ý dùng không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_05','V1004','阮明',5,'对，我刚用小电锅煮完汤，一拔插头，插座直接冒黑烟，我当时都吓懵了。','duì ， wǒ gāng yòng xiǎo diàn guō zhǔ wán tāng ， yī bá chā tóu ， chā zuò zhí jiē mào hēi yān ， wǒ dāng shí dōu xià měng le 。','Dạ đúng ạ, cháu vừa dùng nồi điện nhỏ nấu canh xong, vừa rút phích cắm ra là ổ cắm bốc khói đen luôn, lúc đó cháu sợ chết khiếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_06','V1004','李宿管',6,'我就猜到是大功率违规电器！幸好只是跳闸冒烟，没起火算万幸。我马上带电工过去排查电路。','wǒ jiù cāi dào shì dà gōng lǜ wéi guī diàn qì ！ xìng hǎo zhǐ shì tiào zhá mào yān ， méi qǐ huǒ suàn wàn xìng 。 wǒ mǎ shàng dài diàn gōng guò qù pái chá diàn lù 。','Cô đoán ngay là thiết bị công suất lớn dùng trái quy định mà! May là chỉ nhảy cầu dao với bốc khói thôi, không cháy là còn may đấy. Cô dẫn thợ điện qua kiểm tra đường dây ngay đây.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_07','V1004','阮明',7,'我知道错了阿姨，我再也不敢私用电锅了，一定等电工检查完确认安全再用电。','wǒ zhī dào cuò le ā yí ， wǒ zài yě bù gǎn sī yòng diàn guō le ， yí dìng děng diàn gōng jiǎn chá wán què rèn ān quán zài yòng diàn 。','Cháu biết sai rồi ạ cô, cháu không dám tự ý dùng nồi điện nữa đâu, nhất định đợi thợ điện kiểm tra xong xác nhận an toàn mới dùng điện lại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1004_08','V1004','李宿管',8,'你们先全部到走廊待着，别待在宿舍，防止电路残留隐患伤人，暂时也别碰任何插座开关。','nǐ men xiān quán bù dào zǒu láng dài zhe ， bié dài zài sù shè ， fáng zhǐ diàn lù cán liú yǐn huàn shāng rén ， zàn shí yě bié pèng rèn hé chā zuò kāi guān 。','Các em ra hành lang đứng chờ hết đi, đừng ở trong phòng, đề phòng đường điện còn sót lại rủi ro gây thương tích, tạm thời cũng đừng đụng vào bất cứ ổ cắm hay công tắc nào.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1005','SKC1','晾晒衣物坠落楼下险些砸伤路人，下楼道歉处理',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1005','SIT1005','P1','that_bai_nhe','tuy_y',NULL,'国内居民楼、学生公寓高空坠物属于危险行为，一旦伤人需承担全部赔偿责任，物业会对违规住户通报批评。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_01','V1005','阮明',1,'阿姨！真的非常对不起！刚刚我阳台的衣服掉下来，差点砸到您了！','ā yí ！ zhēn de fēi cháng duì bù qǐ ！ gāng gāng wǒ yáng tái de yī fú diào xià lái ， chà diǎn zá dào nín le ！','Cô ơi! Cháu xin lỗi cô thật sự ạ! Vừa nãy quần áo phơi ở ban công nhà cháu rơi xuống, suýt nữa trúng cô rồi!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_02','V1005','王阿姨',2,'哎哟小伙子，你这衣服突然掉下来，吓我一大跳，还好我躲得快！','āi yō xiǎo huǒ zi ， nǐ zhè yī fú tū rán diào xià lái ， xià wǒ yī dà tiào ， hái hǎo wǒ duǒ dé kuài ！','Ôi chàng trai này, quần áo của cháu tự nhiên rơi xuống làm cô giật cả mình, may mà cô né kịp đấy!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_03','V1005','阮明',3,'都怪我没固定好晾衣架，太粗心了，我现在马上把衣服捡起来，真的抱歉。','dōu guài wǒ méi gù dìng hǎo liàng yī jià ， tài cū xīn le ， wǒ xiàn zài mǎ shàng bǎ yī fú jiǎn qǐ lái ， zhēn de bào qiàn 。','Tại cháu không cột chắc giá phơi đồ, sơ suất quá, cháu nhặt đồ lên ngay đây, thật sự xin lỗi cô.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_04','V1005','王阿姨',4,'你这孩子也太不当心了！楼下人来人往的，万一砸到人，那可不是小事！','nǐ zhè hái zi yě tài bù dàng xīn le ！ lóu xià rén lái rén wǎng de ， wàn yī zá dào rén ， nà kě bú shì xiǎo shì ！','Cháu đúng là bất cẩn quá đấy! Dưới này người qua lại nườm nượp, lỡ mà trúng ai đó thì không phải chuyện nhỏ đâu!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_05','V1005','阮明',5,'我知道错了，以后晾晒衣服一定牢牢固定，绝对不会再出现这种情况了。','wǒ zhī dào cuò le ， yǐ hòu liàng shài yī fú yí dìng láo láo gù dìng ， jué duì bú huì zài chū xiàn zhè zhǒng qíng kuàng le 。','Cháu biết lỗi rồi ạ, sau này phơi đồ cháu nhất định sẽ cột thật chắc, tuyệt đối không để xảy ra chuyện này nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_06','V1005','王阿姨',6,'光嘴上说有什么用？刚才楼下还有小朋友在玩，要是砸到小孩，你负担得起吗？','guāng zuǐ shàng shuō yǒu shén me yòng ？ gāng cái lóu xià hái yǒu xiǎo péng yǒu zài wán ， yào shì zá dào xiǎo hái ， nǐ fù dān dé qǐ ma ？','Nói suông thì có ích gì? Vừa nãy dưới này còn có mấy đứa nhỏ đang chơi nữa, nếu trúng phải trẻ con thì cháu gánh nổi trách nhiệm không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_07','V1005','阮明',7,'是我考虑太不周全了，完全没注意楼下有小孩，我等下就换个稳固的晾晒架子。','shì wǒ kǎo lǜ tài bù zhōu quán le ， wán quán méi zhù yì lóu xià yǒu xiǎo hái ， wǒ děng xià jiù huàn gè wěn gù de liàng shài jià zi 。','Đúng là cháu suy nghĩ không chu đáo, hoàn toàn không để ý dưới này có trẻ con, lát nữa cháu đổi ngay cái giá phơi chắc chắn hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1005_08','V1005','王阿姨',8,'行吧，这次我就不跟宿管反映了，下次再敢这样，我直接上报物业！','xíng ba ， zhè cì wǒ jiù bù gēn sù guǎn fǎn yìng le ， xià cì zài gǎn zhè yàng ， wǒ zhí jiē shàng bào wù yè ！','Thôi được rồi, lần này cô không báo với quản lý ký túc xá đâu, lần sau mà còn tái diễn thế này, cô báo thẳng lên ban quản lý đấy!','AM07') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1006','SKC1','夜间突发眩晕耳鸣无法行走，拨打校内24小时应急电话',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1006','SIT1006','P1','suon_se','ban_chinh_thuc',NULL,'国内高校设有24小时学生应急值班专线，仅限夜间突发身体、安全险情使用，日常小事不建议拨打。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_01','V1006','阮明',1,'老师您好，我是留学生公寓6栋301的学生阮明，我现在身体特别不舒服。','lǎo shī nín hǎo ， wǒ shì liú xué shēng gōng yù 6 dòng 301 de xué shēng ruǎn míng ， wǒ xiàn zài shēn tǐ tè bié bù shū fú 。','Thầy ơi, em là Nguyễn Minh, sinh viên phòng 301 tòa 6 khu ký túc xá lưu học sinh, hiện giờ em thấy rất khó chịu trong người ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_02','V1006','王老师',2,'别着急，慢慢说，具体哪里不舒服？是什么症状？','bié zháo jí ， màn màn shuō ， jù tǐ nǎ lǐ bù shū fú ？ shì shén me zhèng zhuàng ？','Em đừng vội, cứ từ từ nói, cụ thể là khó chịu ở đâu? Triệu chứng thế nào?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_03','V1006','阮明',3,'我突然耳鸣得特别厉害，还天旋地转的，头晕得根本站不起来、走不了路。','wǒ tū rán ěr míng dé tè bié lì hài ， hái tiān xuán dì zhuàn de ， tóu yūn dé gēn běn zhàn bù qǐ lái 、 zǒu bù liǎo lù 。','Em tự nhiên bị ù tai rất nặng, còn thấy trời đất quay cuồng nữa, chóng mặt đến mức không đứng dậy nổi, không đi lại được ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_04','V1006','王老师',4,'你宿舍现在有人陪你吗？身边有没有止痛药或者缓解头晕的药？','nǐ sù shè xiàn zài yǒu rén péi nǐ ma ？ shēn biān yǒu méi yǒu zhǐ tòng yào huò zhě huǎn jiě tóu yūn de yào ？','Trong phòng bây giờ có ai ở cùng em không? Bên cạnh có thuốc giảm đau hay thuốc chống chóng mặt gì không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_05','V1006','阮明',5,'我室友今天回家了，宿舍就我一个人，我也没备任何药品，现在特别难受。','wǒ shì yǒu jīn tiān huí jiā le ， sù shè jiù wǒ yí gè rén ， wǒ yě méi bèi rèn hé yào pǐn ， xiàn zài tè bié nán shòu 。','Bạn cùng phòng em hôm nay về nhà rồi, phòng chỉ có mình em thôi, em cũng không có sẵn thuốc gì cả, giờ khó chịu lắm ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_06','V1006','王老师',6,'明白，你千万别乱动，靠在床边好好坐着或者躺着，我立刻联系校应急医护人员上楼。','míng bái ， nǐ qiān wàn bié luàn dòng ， kào zài chuáng biān hǎo hǎo zuò zhe huò zhě tǎng zhe ， wǒ lì kè lián xì xiào yìng jí yī hù rén yuán shàng lóu 。','Được rồi, em tuyệt đối đừng cử động lung tung, cứ ngồi hoặc nằm yên dựa vào giường, thầy liên hệ ngay nhân viên y tế cấp cứu của trường lên phòng em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_07','V1006','阮明',7,'麻烦您快一点，我闭上眼睛也一直头晕，有点撑不住了。','má fán nín kuài yì diǎn ， wǒ bì shàng yǎn jīng yě yì zhí tóu yūn ， yǒu diǎn chēng bú zhù le 。','Phiền thầy nhanh giúp em với, em nhắm mắt lại vẫn cứ chóng mặt, có vẻ không trụ nổi nữa rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1006_08','V1006','王老师',8,'放心，医护人员五分钟内就到，电话别挂，有任何不舒服随时跟我说。','fàng xīn ， yī hù rén yuán wǔ fēn zhōng nèi jiù dào ， diàn huà bié guà ， yǒu rèn hé bù shū fú suí shí gēn wǒ shuō 。','Yên tâm đi, nhân viên y tế năm phút nữa sẽ tới, đừng cúp máy nhé, có gì khó chịu cứ nói với thầy ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1007','SKC1','网约车司机恶意绕道加价，拨打平台客服紧急维权',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1007','SIT1007','P1','twist','chinh_thuc',NULL,'国内网约车全程平台计价，司机私下索要现金加价属于违规，乘客可直接留存录音、行程记录投诉全额退款。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_01','V1007','阮明',1,'您好，我要投诉刚刚接单的网约车司机，他故意绕路，还私下跟我加价！','nín hǎo ， wǒ yào tóu sù gāng gāng jiē dān de wǎng yuē chē sī jī ， tā gù yì rào lù ， hái sī xià gēn wǒ jiā jià ！','Chào anh/chị, tôi muốn khiếu nại tài xế xe công nghệ vừa nhận chuyến của tôi, anh ta cố tình đi vòng đường, còn tự ý đòi tôi trả thêm tiền!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_02','V1007','客服',2,'您好先生，麻烦提供一下本次出行的订单编号，我调取行程记录帮您核实。','nín hǎo xiān shēng ， má fán tí gōng yī xià běn cì chū xíng de dìng dān biān hào ， wǒ diào qǔ xíng chéng jì lù bāng nín hé shí 。','Chào anh, phiền anh cung cấp mã đơn hàng của chuyến đi này, tôi sẽ tra cứu lịch trình để xác minh giúp anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_03','V1007','阮明',3,'订单编号是724915。明明导航是直达路线，他非要故意绕远，车费凭空多了不少。','dìng dān biān hào shì 724915。 míng míng dǎo háng shì zhí dá lù xiàn ， tā fēi yào gù yì rào yuǎn ， chē fèi píng kōng duō le bù shǎo 。','Mã đơn hàng là 724915. Rõ ràng bản đồ chỉ đường thẳng mà anh ta cứ cố tình đi vòng, tiền cước tự nhiên đội lên không ít.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_04','V1007','客服',4,'您稍等，我查询一下行程轨迹……确实，多条路段偏离了导航路线，非常抱歉给您带来不好的体验。','nín shāo děng ， wǒ chá xún yī xià xíng chéng guǐ jì …… què shí ， duō tiáo lù duàn piān lí le dǎo háng lù xiàn ， fēi cháng bào qiàn gěi nín dài lái bù hǎo de tǐ yàn 。','Anh chờ chút, tôi kiểm tra lộ trình di chuyển... đúng là có nhiều đoạn đường lệch khỏi tuyến chỉ đường, tôi thành thật xin lỗi vì đã mang đến trải nghiệm không tốt cho anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_05','V1007','阮明',5,'不止绕路，司机态度还特别差，不肯线上结算，非要我额外给他现金。','bù zhǐ rào lù ， sī jī tài dù hái tè bié chà ， bù kěn xiàn shàng jié suàn ， fēi yào wǒ é wài gěi tā xiàn jīn 。','Không chỉ đi vòng đường, thái độ của tài xế còn rất tệ, không chịu thanh toán qua ứng dụng, cứ đòi tôi trả thêm tiền mặt.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_06','V1007','客服',6,'了解了，这属于司机违规加价行为。我们会对司机进行处罚，多收的费用会原路退回您的账户。','liǎo jiě le ， zhè shǔ yú sī jī wéi guī jiā jià xíng wéi 。 wǒ men huì duì sī jī jìn xíng chǔ fá ， duō shōu de fèi yòng huì yuán lù tuì huí nín de zhàng hù 。','Tôi hiểu rồi, đây là hành vi thu thêm tiền trái quy định của tài xế. Chúng tôi sẽ xử phạt tài xế này, khoản phí thu thêm sẽ được hoàn trả lại đúng vào tài khoản của anh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_07','V1007','阮明',7,'大概多久能处理完？我之后还要经常打车上学，很怕再遇到这种情况。','dà gài duō jiǔ néng chǔ lǐ wán ？ wǒ zhī hòu hái yào jīng cháng dǎ chē shàng xué ， hěn pà zài yù dào zhè zhǒng qíng kuàng 。','Khoảng bao lâu thì xử lý xong? Sau này tôi vẫn phải thường xuyên đặt xe đi học, tôi rất sợ lại gặp phải tình huống như thế này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_08','V1007','客服',8,'常规退款需要1\-3个工作日，我这边给您加急标记工单，优先处理。','cháng guī tuì kuǎn xū yào 1\-3 gè gōng zuò rì ， wǒ zhè biān gěi nín jiā jí biāo jì gōng dān ， yōu xiān chǔ lǐ 。','Hoàn tiền thông thường cần 1-3 ngày làm việc, tôi sẽ đánh dấu khẩn cho yêu cầu của anh để được xử lý ưu tiên.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_09','V1007','阮明',9,'好的，麻烦您尽量快一点。','hǎo de ， má fán nín jǐn liàng kuài yì diǎn 。','Vâng, phiền anh/chị cố gắng xử lý nhanh giúp tôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1007_10','V1007','客服',10,'处理结果会以短信通知您，后续有问题随时联系我们。','chǔ lǐ jié guǒ huì yǐ duǎn xìn tōng zhī nín ， hòu xù yǒu wèn tí suí shí lián xì wǒ men 。','Kết quả xử lý sẽ được thông báo cho anh qua tin nhắn, nếu sau này còn vấn đề gì xin cứ liên hệ với chúng tôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1008','SKC1','骑行共享单车摔倒扭伤，向路人求助简单伤口处理',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1008','SIT1008','P1','suon_se','tuy_y',NULL,'国内很多年轻人会随身备简易消毒用品，路人遇到受伤行人大多愿意主动提供临时帮助。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1008_01','V1008','阮明',1,'你好，不好意思打扰一下，我骑车摔倒了，膝盖擦伤流血了，你有碘伏吗？','nǐ hǎo ， bù hǎo yì sī dǎ rǎo yī xià ， wǒ qí chē shuāi dǎo le ， xī gài cā shāng liú xiě le ， nǐ yǒu diǎn fú ma ？','Chào chị, xin lỗi làm phiền chị một chút, em bị ngã xe đạp, đầu gối trầy xước chảy máu rồi, chị có cồn i-ốt không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1008_02','V1008','刘姑娘',2,'天呐，你摔得看着好疼！我刚好带了消毒湿巾和创可贴，我帮你处理一下。','tiān nà ， nǐ shuāi dé kàn zhe hǎo téng ！ wǒ gāng hǎo dài le xiāo dú shī jīn hé chuàng kě tiē ， wǒ bāng nǐ chǔ lǐ yī xià 。','Trời ơi, nhìn em ngã đau vậy! May quá chị có mang theo khăn giấy khử trùng với băng cá nhân đây, để chị xử lý giúp em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1008_03','V1008','阮明',3,'太谢谢你了！刚刚刹车打滑，直接摔在路边，伤口一直流血，我都不知道怎么办。','tài xiè xiè nǐ le ！ gāng gāng shā chē dǎ huá ， zhí jiē shuāi zài lù biān ， shāng kǒu yì zhí liú xiě ， wǒ dōu bù zhī dào zěn me bàn 。','Cảm ơn chị nhiều lắm! Vừa nãy em phanh gấp bị trượt bánh, ngã ngay ra lề đường luôn, vết thương cứ chảy máu mãi, em không biết phải làm sao nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1008_04','V1008','刘姑娘',4,'你先坐台阶上别动，别来回蹭，不然伤口容易沾灰尘发炎。','nǐ xiān zuò tái jiē shàng bié dòng ， bié lái huí cèng ， bù rán shāng kǒu róng yì zhān huī chén fā yán 。','Em ngồi yên trên bậc thềm đi, đừng cử động qua lại, không thì vết thương dễ dính bụi bẩn rồi bị viêm đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1008_05','V1008','阮明',5,'好，辛苦你了。我平时没带急救用品的习惯，这次太疏忽了。','hǎo ， xīn kǔ nǐ le 。 wǒ píng shí méi dài jí jiù yòng pǐn de xí guàn ， zhè cì tài shū hū le 。','Dạ vâng, chị vất vả rồi. Em bình thường không có thói quen mang theo đồ sơ cứu, lần này sơ suất quá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1008_06','V1008','刘姑娘',6,'没事，举手之劳。不过你下次骑车慢点，雨天路面滑，特别容易打滑摔倒。','méi shì ， jǔ shǒu zhī láo 。 bù guò nǐ xià cì qí chē màn diǎn ， yǔ tiān lù miàn huá ， tè bié róng yì dǎ huá shuāi dǎo 。','Không sao đâu, chuyện nhỏ thôi mà. Nhưng lần sau em đi xe chậm lại nhé, trời mưa đường trơn, rất dễ trượt ngã đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1008_07','V1008','阮明',7,'我记住啦，以后一定注意。处理完我自己慢慢收拾车子，不耽误你赶路。','wǒ jì zhù la ， yǐ hòu yí dìng zhù yì 。 chǔ lǐ wán wǒ zì jǐ màn màn shōu shí chē zi ， bù dān wù nǐ gǎn lù 。','Em nhớ rồi ạ, sau này nhất định sẽ chú ý. Xử lý xong em tự dọn xe từ từ, không làm chậm trễ việc của chị đâu.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1009','SKC1','外出迷路手机没电关机，向商铺店员借手机联系好友',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1009','SIT1009','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内商铺店主出于防骗顾虑，大多不愿外借私人手机，街边共享充电宝是外出应急充电主流方案。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_01','V1009','阮明',1,'老板您好，打扰一下，我的手机没电关机了，能不能借您手机打个短电话？','lǎo bǎn nín hǎo ， dǎ rǎo yī xià ， wǒ de shǒu jī méi diàn guān jī le ， néng bù néng jiè nín shǒu jī dǎ gè duǎn diàn huà ？','Chào anh chủ, phiền anh chút ạ, điện thoại em hết pin tắt máy rồi, anh cho em mượn điện thoại gọi nhờ một cuộc ngắn được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_02','V1009','赵老板',2,'借手机可以，我先问下，你要打给谁？大概打多久？','jiè shǒu jī kě yǐ ， wǒ xiān wèn xià ， nǐ yào dǎ gěi shuí ？ dà gài dǎ duō jiǔ ？','Cho mượn thì được, nhưng để tôi hỏi trước đã, cậu định gọi cho ai? Gọi khoảng bao lâu?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_03','V1009','阮明',3,'我和同学出门走散迷路了，就两分钟，跟他说下我的位置就行，很快的。','wǒ hé tóng xué chū mén zǒu sàn mí lù le ， jiù liǎng fēn zhōng ， gēn tā shuō xià wǒ de wèi zhì jiù xíng ， hěn kuài de 。','Em với bạn học đi chơi bị lạc nhau, chỉ hai phút thôi ạ, em nói vị trí của em cho bạn ấy là được rồi, nhanh lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_04','V1009','赵老板',4,'哎，实在不好意思，现在外面骗子太多，陌生人借手机的情况很乱，我不太敢直接借你。','āi ， shí zài bù hǎo yì sī ， xiàn zài wài miàn piàn zi tài duō ， mò shēng rén jiè shǒu jī de qíng kuàng hěn luàn ， wǒ bù tài gǎn zhí jiē jiè nǐ 。','Ây, thật ngại quá, giờ ngoài đường lừa đảo nhiều lắm, chuyện người lạ mượn điện thoại cũng phức tạp, tôi không dám cho mượn thẳng như vậy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_05','V1009','阮明',5,'我不是骗子的！我是旁边大学的留学生，我可以给您看我的居留卡，证明我的身份。','wǒ bú shì piàn zi de ！ wǒ shì páng biān dà xué de liú xué shēng ， wǒ kě yǐ gěi nín kàn wǒ de jū liú kǎ ， zhèng míng wǒ de shēn fèn 。','Em không phải lừa đảo đâu! Em là du học sinh của trường đại học gần đây, em có thể cho anh xem thẻ cư trú để chứng minh thân phận.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_06','V1009','赵老板',6,'我理解你着急，但我也不方便仔细核对证件，风险太大了。你可以去对面便利店租个充电宝充电。','wǒ lǐ jiě nǐ zháo jí ， dàn wǒ yě bù fāng biàn zǐ xì hé duì zhèng jiàn ， fēng xiǎn tài dà le 。 nǐ kě yǐ qù duì miàn biàn lì diàn zū gè chōng diàn bǎo chōng diàn 。','Tôi hiểu cậu đang gấp, nhưng tôi cũng không tiện kiểm tra giấy tờ kỹ càng, rủi ro lớn quá. Cậu có thể sang cửa hàng tiện lợi đối diện thuê sạc dự phòng mà sạc.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_07','V1009','阮明',7,'啊……好吧，那我现在过去试试，麻烦您了。','a …… hǎo ba ， nà wǒ xiàn zài guò qù shì shì ， má fán nín le 。','À... vâng, vậy em qua bên đó thử xem sao, phiền anh rồi ạ.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1009_08','V1009','赵老板',8,'多多包涵哈，我们开店也是怕出问题，希望你理解。','duō duō bāo hán hā ， wǒ men kāi diàn yě shì pà chū wèn tí ， xī wàng nǐ lǐ jiě 。','Mong cậu thông cảm nhé, chúng tôi buôn bán cũng sợ xảy ra chuyện, hy vọng cậu hiểu cho.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1010','SKC1','背包在商场被小偷顺手牵羊，前往附近派出所做笔录',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1010','SIT1010','P1','twist','chinh_thuc',NULL,'外国人丢失随身财物报案，需携带护照、居留许可，笔录信息会同步登记出入境系统。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_01','V1010','阮明',1,'警官您好，我要报案，我的背包在商场被人偷走了。','jǐng guān nín hǎo ， wǒ yào bào àn ， wǒ de bēi bāo zài shāng chǎng bèi rén tōu zǒu le 。','Chào anh công an, tôi muốn trình báo, ba lô của tôi bị người ta lấy trộm trong trung tâm thương mại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_02','V1010','周警官',2,'先坐，不用慌。报一下你的姓名、国籍，还有居留许可的相关信息。','xiān zuò ， bù yòng huāng 。 bào yī xià nǐ de xìng míng 、 guó jí ， hái yǒu jū liú xǔ kě de xiāng guān xìn xī 。','Mời ngồi trước đã, không cần hoảng. Anh cho tôi biết họ tên, quốc tịch, và thông tin liên quan đến giấy phép cư trú.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_03','V1010','阮明',3,'我叫阮明，是越南留学生。背包里有我的银行卡、耳机，还有上课用的笔记。','wǒ jiào ruǎn míng ， shì yuè nán liú xué shēng 。 bēi bāo lǐ yǒu wǒ de yín háng kǎ 、 ěr jī ， hái yǒu shàng kè yòng de bǐ jì 。','Tôi tên Nguyễn Minh, là du học sinh Việt Nam. Trong ba lô có thẻ ngân hàng, tai nghe, và vở ghi chép đi học của tôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_04','V1010','周警官',4,'具体是什么时间、商场哪一层、哪个位置丢的？仔细回忆清楚。','jù tǐ shì shén me shí jiān 、 shāng chǎng nǎ yī céng 、 nǎ ge wèi zhì diū de ？ zǐ xì huí yì qīng chǔ 。','Cụ thể là mất vào lúc nào, ở tầng nào, vị trí nào trong trung tâm thương mại? Anh nhớ lại cho kỹ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_05','V1010','阮明',5,'大概四十分钟前，我在商场餐饮区取餐，就离开座位几十秒，回头背包就没了。','dà gài sì shí fēn zhōng qián ， wǒ zài shāng chǎng cān yǐn qū qǔ cān ， jiù lí kāi zuò wèi jǐ shí miǎo ， huí tóu bēi bāo jiù méi le 。','Khoảng bốn mươi phút trước, tôi đang lấy đồ ăn ở khu ẩm thực, chỉ rời khỏi chỗ ngồi vài chục giây, quay lại thì ba lô đã biến mất.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_06','V1010','周警官',6,'我跟你说实话，商场人流量太大，人员混杂，就算调取监控，找回物品的难度也不小。','wǒ gēn nǐ shuō shí huà ， shāng chǎng rén liú liàng tài dà ， rén yuán hùn zá ， jiù suàn diào qǔ jiān kòng ， zhǎo huí wù pǐn de nán dù yě bù xiǎo 。','Tôi nói thật với anh, trung tâm thương mại đông người qua lại, thành phần phức tạp, dù có trích xuất camera thì việc tìm lại đồ cũng không dễ đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_07','V1010','阮明',7,'啊？那怎么办……我的银行卡还没挂失，万一被盗刷就麻烦了。请问有银行挂失电话吗？','a ？ nà zěn me bàn …… wǒ de yín háng kǎ hái méi guà shī ， wàn yī bèi dào shuā jiù má fán le 。 qǐng wèn yǒu yín háng guà shī diàn huà ma ？','Hả? Vậy phải làm sao đây... Thẻ ngân hàng của tôi chưa báo mất, lỡ bị quẹt trộm thì phiền lắm. Anh cho tôi hỏi số điện thoại báo mất thẻ ngân hàng được không ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_08','V1010','周警官',8,'我把挂失电话写纸条给你，你先做完笔录，尽快联系银行冻结卡片，减少损失。','wǒ bǎ guà shī diàn huà xiě zhǐ tiáo gěi nǐ ， nǐ xiān zuò wán bǐ lù ， jǐn kuài lián xì yín háng dòng jié kǎ piàn ， jiǎn shǎo sǔn shī 。','Tôi ghi số điện thoại báo mất ra giấy cho anh, anh làm biên bản xong trước đã, rồi liên hệ ngân hàng khóa thẻ càng sớm càng tốt để giảm thiệt hại.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1010_09','V1010','阮明',9,'好，谢谢警官，我马上配合做笔录。','hǎo ， xiè xiè jǐng guān ， wǒ mǎ shàng pèi hé zuò bǐ lù 。','Vâng, cảm ơn anh công an, tôi sẽ hợp tác làm biên bản ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1011','SKC1','暴雨导致郊区公交全线停运，求助社区工作人员临时安置',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1011','SIT1011','P1','suon_se','ban_chinh_thuc',NULL,'国内社区服务中心对受极端天气滞留的路人提供免费临时休息、热水充电等便民服务。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_01','V1011','阮明',1,'您好，外面暴雨太大，所有公交都停运了，我回不了学校，能在这边临时待一会吗？','nín hǎo ， wài miàn bào yǔ tài dà ， suǒ yǒu gōng jiāo dōu tíng yùn le ， wǒ huí bù liǎo xué xiào ， néng zài zhè biān lín shí dài yī huì ma ？','Chào chị, ngoài trời mưa to quá, xe buýt dừng chạy hết rồi, em không về trường được, cho em tạm trú ở đây một lát được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_02','V1011','小吴',2,'同学别着急，你是哪个学校的？身上有没有带雨具？','tóng xué bié zháo jí ， nǐ shì nǎ ge xué xiào de ？ shēn shàng yǒu méi yǒu dài yǔ jù ？','Em đừng lo, em học trường nào vậy? Có mang theo áo mưa hay ô gì không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_03','V1011','阮明',3,'我是外国语大学的留学生，出门没带伞，手机也快没电了，根本打不到车。','wǒ shì wài guó yǔ dà xué de liú xué shēng ， chū mén méi dài sǎn ， shǒu jī yě kuài méi diàn le ， gēn běn dǎ bú dào chē 。','Em là du học sinh trường Đại học Ngoại ngữ, lúc ra ngoài không mang ô, điện thoại cũng sắp hết pin, gọi xe cũng không được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_04','V1011','小吴',4,'我懂，现在路面积水太深，网约车也进不来。你可以在我们社区服务站临时休息，等雨小再说。','wǒ dǒng ， xiàn zài lù miàn jī shuǐ tài shēn ， wǎng yuē chē yě jìn bù lái 。 nǐ kě yǐ zài wǒ men shè qū fú wù zhàn lín shí xiū xī ， děng yǔ xiǎo zài shuō 。','Chị hiểu, giờ đường ngập nước sâu quá, xe công nghệ cũng không vào được. Em cứ nghỉ tạm ở trạm dịch vụ cộng đồng của chị đây, đợi mưa nhỏ bớt rồi tính tiếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_05','V1011','阮明',5,'太感谢您了！我本来还赶着回去上晚自习，这下肯定赶不上了。','tài gǎn xiè nín le ！ wǒ běn lái hái gǎn zhe huí qù shàng wǎn zì xí ， zhè xià kěn dìng gǎn bù shàng le 。','Em cảm ơn chị nhiều lắm! Em vốn định về kịp giờ tự học tối, giờ chắc chắn không kịp rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_06','V1011','小吴',6,'没事，我给你倒杯热水，你抽空跟辅导员说下情况，请假报备一下。','méi shì ， wǒ gěi nǐ dào bēi rè shuǐ ， nǐ chōu kòng gēn fǔ dǎo yuán shuō xià qíng kuàng ， qǐng jià bào bèi yī xià 。','Không sao đâu, để chị rót cho em cốc nước nóng, em tranh thủ báo tình hình cho thầy cô cố vấn, xin nghỉ phép một tiếng nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_07','V1011','阮明',7,'好，我借您这边的插座充下电，等雨势变小了再想办法回学校。','hǎo ， wǒ jiè nín zhè biān de chā zuò chōng xià diàn ， děng yǔ shì biàn xiǎo le zài xiǎng bàn fǎ huí xué xiào 。','Vâng, em mượn ổ cắm điện bên chị sạc pin một chút, đợi mưa nhỏ lại em sẽ tìm cách về trường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1011_08','V1011','小吴',8,'安心待着，暴雨天路况危险，千万别强行出门涉水。','ān xīn dài zhe ， bào yǔ tiān lù kuàng wēi xiǎn ， qiān wàn bié qiáng xíng chū mén shè shuǐ 。','Cứ yên tâm ở đây đi, trời mưa to đường sá nguy hiểm lắm, tuyệt đối đừng cố ra ngoài lội nước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1012','SKC1','街边小吃食物中毒集体腹痛，拨打市场监管热线投诉',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1012','SIT1012','P1','twist','chinh_thuc',NULL,'餐饮食物中毒维权需要保留消费凭证、医院诊断单据，监管部门会现场抽检食材，属实可要求商家全额赔偿医药费。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_01','V1012','阮明',1,'您好，我要举报街边小吃摊！我和两个同学吃完之后，全都腹痛、拉肚子，应该是食物中毒了。','nín hǎo ， wǒ yào jǔ bào jiē biān xiǎo chī tān ！ wǒ hé liǎng gè tóng xué chī wán zhī hòu ， quán dōu fù tòng 、 lā dù zi ， yīng gāi shì shí wù zhòng dú le 。','Chào chị, tôi muốn tố cáo một quán ăn vặt ven đường! Tôi và hai bạn học sau khi ăn xong đều bị đau bụng, tiêu chảy, chắc là ngộ độc thực phẩm rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_02','V1012','接线员',2,'麻烦您提供一下小吃摊的具体地址、摊位名称，还有你们的就餐时间。','má fán nín tí gōng yī xià xiǎo chī tān de jù tǐ dì zhǐ 、 tān wèi míng chēng ， hái yǒu nǐ men de jiù cān shí jiān 。','Phiền anh chị cung cấp địa chỉ cụ thể của quán ăn vặt, tên gian hàng, và thời gian các bạn ăn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_03','V1012','阮明',3,'就在我们学校南门的小巷子里，是一家无名炸串摊，今天傍晚六点左右我们在那吃的。','jiù zài wǒ men xué xiào nán mén de xiǎo xiàng zi lǐ ， shì yī jiā wú míng zhà chuàn tān ， jīn tiān bàng wǎn liù diǎn zuǒ yòu wǒ men zài nà chī de 。','Ngay trong con hẻm nhỏ ở cổng nam trường tôi, là một quán xiên chiên không có tên, chiều nay khoảng sáu giờ chúng tôi ăn ở đó.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_04','V1012','接线员',4,'了解了。请问你们现在身体状况怎么样？有没有去医院开具诊断证明？','liǎo jiě le 。 qǐng wèn nǐ men xiàn zài shēn tǐ zhuàng kuàng zěn me yàng ？ yǒu méi yǒu qù yī yuàn kāi jù zhěn duàn zhèng míng ？','Tôi đã rõ. Xin hỏi hiện giờ tình trạng sức khỏe của các bạn thế nào? Đã đi bệnh viện xin giấy chẩn đoán chưa?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_05','V1012','阮明',5,'我们刚从社区诊所看完，医生确诊是不洁食物引发的肠胃不适。','wǒ men gāng cóng shè qū zhěn suǒ kàn wán ， yī shēng què zhěn shì bù jié shí wù yǐn fā de cháng wèi bù shì 。','Chúng tôi vừa khám xong ở phòng khám cộng đồng, bác sĩ chẩn đoán là rối loạn tiêu hóa do thức ăn không sạch gây ra.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_06','V1012','接线员',6,'需要您携带就诊单据、消费记录，在工作日到辖区监管所现场登记投诉。','xū yào nín xié dài jiù zhěn dān jù 、 xiāo fèi jì lù ， zài gōng zuò rì dào xiá qū jiān guǎn suǒ xiàn chǎng dēng jì tóu sù 。','Anh chị cần mang theo hóa đơn khám bệnh, chứng từ chi tiêu, đến cơ quan quản lý khu vực vào ngày làm việc để đăng ký khiếu nại trực tiếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_07','V1012','阮明',7,'我们这周课程很多，下周才能过去登记，万一这几天摊位跑路、关门怎么办？','wǒ men zhè zhōu kè chéng hěn duō ， xià zhōu cái néng guò qù dēng jì ， wàn yī zhè jǐ tiān tān wèi pǎo lù 、 guān mén zěn me bàn ？','Tuần này chúng tôi lịch học dày lắm, tuần sau mới đi đăng ký được, lỡ mấy ngày này quán bỏ trốn hoặc đóng cửa thì sao?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_08','V1012','接线员',8,'您不用担心，我们会立刻安排工作人员上门核查，暂扣摊位食材留存证据，固定线索。','nín bù yòng dān xīn ， wǒ men huì lì kè ān pái gōng zuò rén yuán shàng mén hé chá ， zàn kòu tān wèi shí cái liú cún zhèng jù ， gù dìng xiàn suǒ 。','Anh chị đừng lo, chúng tôi sẽ cử người đến kiểm tra ngay, tạm giữ nguyên liệu của quán để lưu làm bằng chứng, cố định manh mối.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1012_09','V1012','阮明',9,'那就好，辛苦你们尽快处理。','nà jiù hǎo ， xīn kǔ nǐ men jǐn kuài chǔ lǐ 。','Vậy thì tốt quá, phiền các anh chị xử lý sớm giúp chúng tôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1013','SKC1','居留许可卡片断裂损毁，出入境大厅申请临时通行纸质证明',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1013','SIT1013','P1','suon_se','chinh_thuc',NULL,'外国人居留许可损毁、丢失均无法单独出行，临时纸质通行证明仅限国内短期交通出行使用，不能替代正式居留卡。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_01','V1013','阮明',1,'您好，我的外国人居留许可不小心折断损坏了，刷不了卡，想办理临时通行证明。','nín hǎo ， wǒ de wài guó rén jū liú xǔ kě bù xiǎo xīn zhé duàn sǔn huài le ， shuā bù liǎo kǎ ， xiǎng bàn lǐ lín shí tōng xíng zhèng míng 。','Chào chị, thẻ cư trú người nước ngoài của tôi vô tình bị gãy hỏng, không quẹt được nữa, tôi muốn làm giấy chứng nhận thông hành tạm thời.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_02','V1013','刘柜员',2,'麻烦先出示一下你的护照，还有破损的居留卡，我先帮你核验信息。','má fán xiān chū shì yī xià nǐ de hù zhào ， hái yǒu pò sǔn de jū liú kǎ ， wǒ xiān bāng nǐ hé yàn xìn xī 。','Phiền anh xuất trình hộ chiếu, và cả thẻ cư trú bị hỏng, để tôi kiểm tra thông tin trước đã.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_03','V1013','阮明',3,'您看，卡片中间裂开了，所有设备都识别不了。我下周还要坐高铁外出办事，特别着急。','nín kàn ， kǎ piàn zhōng jiān liè kāi le ， suǒ yǒu shè bèi dōu shí bié bù liǎo 。 wǒ xià zhōu hái yào zuò gāo tiě wài chū bàn shì ， tè bié zháo jí 。','Chị xem, thẻ bị nứt ngay giữa, mọi thiết bị đều không nhận diện được. Tuần sau tôi còn phải đi tàu cao tốc để giải quyết việc, gấp lắm ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_04','V1013','刘柜员',4,'我看到了，破损的居留卡已经失效，不能正常使用了。临时纸质证明有效期只有七天，你注意时间。','wǒ kàn dào le ， pò sǔn de jū liú kǎ yǐ jīng shī xiào ， bù néng zhèng cháng shǐ yòng le 。 lín shí zhǐ zhì zhèng míng yǒu xiào qī zhǐ yǒu qī tiān ， nǐ zhù yì shí jiān 。','Tôi thấy rồi, thẻ cư trú bị hỏng đã mất hiệu lực, không dùng được bình thường nữa. Giấy chứng nhận tạm thời chỉ có hiệu lực bảy ngày thôi, anh chú ý thời hạn nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_05','V1013','阮明',5,'七天完全够我补办新卡了。请问办理这个证明，还需要额外准备其他材料吗？','qī tiān wán quán gòu wǒ bǔ bàn xīn kǎ le 。 qǐng wèn bàn lǐ zhè ge zhèng míng ， hái xū yào é wài zhǔn bèi qí tā cái liào ma ？','Bảy ngày là đủ để tôi làm lại thẻ mới rồi. Cho tôi hỏi làm giấy chứng nhận này có cần chuẩn bị thêm giấy tờ gì khác không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_06','V1013','刘柜员',6,'只需要准备一张一寸白底证件照，填写补办申请表，现场等待半小时就能出证。','zhǐ xū yào zhǔn bèi yī zhāng yī cùn bái dǐ zhèng jiàn zhào ， tián xiě bǔ bàn shēn qǐng biǎo ， xiàn chǎng děng dài bàn xiǎo shí jiù néng chū zhèng 。','Chỉ cần chuẩn bị một ảnh thẻ nền trắng cỡ 1 inch, điền đơn xin cấp lại, chờ tại chỗ nửa tiếng là có giấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_07','V1013','阮明',7,'还好我今天带齐了证件，不然下周出行肯定要被拦下，太耽误事了。','hái hǎo wǒ jīn tiān dài qí le zhèng jiàn ， bù rán xià zhōu chū xíng kěn dìng yào bèi lán xià ， tài dān wù shì le 。','May mà hôm nay tôi mang đủ giấy tờ, không thì tuần sau đi lại chắc chắn bị chặn lại, lỡ việc quá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1013_08','V1013','刘柜员',8,'拿到临时证明后，近期出门务必同时携带护照，配合查验。','ná dào lín shí zhèng míng hòu ， jìn qī chū mén wù bì tóng shí xié dài hù zhào ， pèi hé chá yàn 。','Sau khi nhận giấy chứng nhận tạm thời, thời gian tới ra ngoài nhất định phải mang theo hộ chiếu để phối hợp kiểm tra.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1014','SKC1','签证线上缴费扣款成功但系统未入账，联系出入境财务加急核对',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1014','SIT1014','P1','that_bai_nhe','chinh_thuc',NULL,'政务线上缴费存在银行、政务系统对账时差，窗口开具纸质临时凭证可临时规避审核拦截。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_01','V1014','阮明',1,'陈会计您好，我想咨询一下，我昨天线上续签签证，银行卡已经扣款成功，但系统一直显示未缴费。','chén kuài jì nín hǎo ， wǒ xiǎng zī xún yī xià ， wǒ zuó tiān xiàn shàng xù qiān qiān zhèng ， yín háng kǎ yǐ jīng kòu kuǎn chéng gōng ， dàn xì tǒng yì zhí xiǎn shì wèi jiǎo fèi 。','Chào kế toán Trần, tôi muốn hỏi một chút, hôm qua tôi gia hạn visa trực tuyến, thẻ ngân hàng đã bị trừ tiền thành công, nhưng hệ thống vẫn hiện chưa nộp phí.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_02','V1014','陈会计',2,'你把缴费订单号、银行卡扣款截图，统一发到我的办公邮箱。','nǐ bǎ jiǎo fèi dìng dān hào 、 yín háng kǎ kòu kuǎn jié tú ， tǒng yī fā dào wǒ de bàn gōng yóu xiāng 。','Anh gửi mã đơn thanh toán, cùng ảnh chụp màn hình bị trừ tiền, vào email công tác của tôi nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_03','V1014','阮明',3,'好的，订单号是896421，扣款截图我都保存好了，现在就能发给您。','hǎo de ， dìng dān hào shì 896421， kòu kuǎn jié tú wǒ dōu bǎo cún hǎo le ， xiàn zài jiù néng fā gěi nín 。','Vâng, mã đơn là 896421, ảnh chụp bị trừ tiền tôi đã lưu sẵn rồi, giờ có thể gửi cho chị ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_04','V1014','陈会计',4,'我先跟你说明，这种跨银行缴费延迟入账很常见，需要系统夜间对账，最快明天才能更新状态。','wǒ xiān gēn nǐ shuō míng ， zhè zhǒng kuà yín háng jiǎo fèi yán chí rù zhàng hěn cháng jiàn ， xū yào xì tǒng yè jiān duì zhàng ， zuì kuài míng tiān cái néng gēng xīn zhuàng tài 。','Tôi nói trước với anh, kiểu thanh toán liên ngân hàng bị chậm ghi nhận thế này rất thường gặp, cần hệ thống đối soát vào ban đêm, sớm nhất là ngày mai mới cập nhật được trạng thái.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_05','V1014','阮明',5,'可是我后天就要提交续签审核了，系统显示未缴费，申请会直接被驳回，来不及等明天。','kě shì wǒ hòu tiān jiù yào tí jiāo xù qiān shěn hé le ， xì tǒng xiǎn shì wèi jiǎo fèi ， shēn qǐng huì zhí jiē bèi bó huí ， lái bù jí děng míng tiān 。','Nhưng ngày kia tôi đã phải nộp hồ sơ gia hạn xét duyệt rồi, hệ thống hiện chưa nộp phí thì hồ sơ sẽ bị từ chối ngay, không kịp chờ đến ngày mai đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_06','V1014','陈会计',6,'我理解你的紧急情况，我可以给你开具一份临时缴费凭证，窗口可以凭凭证先受理你的申请材料。','wǒ lǐ jiě nǐ de jǐn jí qíng kuàng ， wǒ kě yǐ gěi nǐ kāi jù yī fèn lín shí jiǎo fèi píng zhèng ， chuāng kǒu kě yǐ píng píng zhèng xiān shòu lǐ nǐ de shēn qǐng cái liào 。','Tôi hiểu tình huống gấp của anh, tôi có thể cấp cho anh một giấy chứng nhận thanh toán tạm thời, quầy tiếp nhận có thể dựa vào đó để tiếp nhận hồ sơ của anh trước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_07','V1014','阮明',7,'太好了！我现在立刻发送截图，麻烦您尽快帮我核对处理。','tài hǎo le ！ wǒ xiàn zài lì kè fā sòng jié tú ， má fán nín jǐn kuài bāng wǒ hé duì chǔ lǐ 。','Tuyệt quá! Tôi gửi ảnh chụp ngay bây giờ, phiền chị kiểm tra xử lý giúp tôi sớm nhất có thể.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1014_08','V1014','陈会计',8,'我今天下班前完成对账核对，如果资金还是未同步，你明天上午再来一趟补录信息。','wǒ jīn tiān xià bān qián wán chéng duì zhàng hé duì ， rú guǒ zī jīn hái shì wèi tóng bù ， nǐ míng tiān shàng wǔ zài lái yī tàng bǔ lù xìn xī 。','Tôi sẽ hoàn thành đối soát trước khi tan làm hôm nay, nếu tiền vẫn chưa đồng bộ thì sáng mai anh ghé lại bổ sung thông tin nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1015','SKC1','论文截止日前电脑硬盘崩溃文件丢失，找授课老师申请延期并借用图书馆设备',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1015','SIT1015','P1','twist','ban_chinh_thuc',NULL,'国内高校论文延期需提交书面说明\+客观事故证明，任课老师无权私自延期，必须上报教务审批。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_01','V1015','阮明',1,'周老师，不好意思打扰您，我遇到突发情况，电脑硬盘突然损坏，整篇毕业论文文件全部丢失了。','zhōu lǎo shī ， bù hǎo yì sī dǎ rǎo nín ， wǒ yù dào tū fā qíng kuàng ， diàn nǎo yìng pán tū rán sǔn huài ， zhěng piān bì yè lùn wén wén jiàn quán bù diū shī le 。','Thầy Chu ơi, xin lỗi đã làm phiền thầy, em gặp sự cố đột xuất, ổ cứng máy tính đột nhiên bị hỏng, toàn bộ file luận văn tốt nghiệp của em mất sạch rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_02','V1015','周教授',2,'怎么会出现这种意外？学院论文截止提交日期就在明天中午，时间非常紧张。','zěn me huì chū xiàn zhè zhǒng yì wài ？ xué yuàn lùn wén jié zhǐ tí jiāo rì qī jiù zài míng tiān zhōng wǔ ， shí jiān fēi cháng jǐn zhāng 。','Sao lại xảy ra chuyện bất ngờ thế này? Hạn nộp luận văn của khoa là trưa mai rồi, thời gian gấp lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_03','V1015','阮明',3,'我之前没有备份文件，现在硬盘完全读取不了，维修店说数据恢复的概率很低。','wǒ zhī qián méi yǒu bèi fèn wén jiàn ， xiàn zài yìng pán wán quán dú qǔ bù liǎo ， wéi xiū diàn shuō shù jù huī fù de gài lǜ hěn dī 。','Trước đó em không sao lưu file, giờ ổ cứng hoàn toàn không đọc được, tiệm sửa máy nói khả năng khôi phục dữ liệu rất thấp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_04','V1015','周教授',4,'我很理解你的突发状况，但学院的截止时间是统一规定的，我个人没办法直接给你延后。','wǒ hěn lǐ jiě nǐ de tū fā zhuàng kuàng ， dàn xué yuàn de jié zhǐ shí jiān shì tǒng yī guī dìng de ， wǒ gè rén méi bàn fǎ zhí jiē gěi nǐ yán hòu 。','Thầy rất hiểu tình huống bất ngờ của em, nhưng thời hạn của khoa là quy định chung, thầy không thể tự ý cho em gia hạn được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_05','V1015','阮明',5,'我知道规则很严格！老师，我能不能申请三天延期？图书馆有备用电脑，我可以通宵重新写完初稿，绝对不拖延太久。','wǒ zhī dào guī zé hěn yán gé ！ lǎo shī ， wǒ néng bù néng shēn qǐng sān tiān yán qī ？ tú shū guǎn yǒu bèi yòng diàn nǎo ， wǒ kě yǐ tōng xiāo chóng xīn xiě wán chū gǎo ， jué duì bù tuō yán tài jiǔ 。','Em biết quy định rất nghiêm ngặt ạ! Thầy ơi, em có thể xin gia hạn ba ngày được không ạ? Thư viện có máy tính dự phòng, em có thể thức trắng đêm viết lại bản nháp, chắc chắn không kéo dài lâu đâu ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_06','V1015','周教授',6,'这样，你先写一份详细的书面情况说明，再附上电脑硬盘损坏的维修单据，我帮你上报教务处申请。','zhè yàng ， nǐ xiān xiě yī fèn xiáng xì de shū miàn qíng kuàng shuō míng ， zài fù shàng diàn nǎo yìng pán sǔn huài de wéi xiū dān jù ， wǒ bāng nǐ shàng bào jiào wù chù shēn qǐng 。','Thế này nhé, em viết một bản trình bày chi tiết bằng văn bản trước, kèm theo hóa đơn sửa chữa ổ cứng bị hỏng, thầy sẽ giúp em báo cáo lên phòng đào tạo xin gia hạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_07','V1015','阮明',7,'太感谢老师了！我现在就去图书馆借设备，马上开始重新赶写论文。','tài gǎn xiè lǎo shī le ！ wǒ xiàn zài jiù qù tú shū guǎn jiè shè bèi ， mǎ shàng kāi shǐ chóng xīn gǎn xiě lùn wén 。','Em cảm ơn thầy nhiều lắm! Em đi thư viện mượn máy ngay bây giờ, bắt tay viết lại luận văn luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1015_08','V1015','周教授',8,'尽量加快进度，教务最多只能审批三天缓冲期，这是最大限度了，千万别再超时。','jǐn liàng jiā kuài jìn dù ， jiào wù zuì duō zhǐ néng shěn pī sān tiān huǎn chōng qī ， zhè shì zuì dà xiàn dù le ， qiān wàn bié zài chāo shí 。','Cố gắng đẩy nhanh tiến độ nhé, phòng đào tạo nhiều nhất chỉ duyệt cho ba ngày gia hạn thôi, đây là giới hạn tối đa rồi, tuyệt đối đừng để quá hạn nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1016','SKC1','出入境预约号当日失效，携带齐全材料现场窗口申请加急受理',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1016','SIT1016','P1','that_bai_nhe','ban_chinh_thuc',NULL,'出入境线上预约实行分时段限号制度，普通出行、学术活动不纳入紧急加急受理范围，仅重大医疗、亲属变故可走绿色通道。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_01','V1016','阮明',1,'你好，我今天预约了签证续签，刚刚扫码显示预约号失效了，我所有办理材料都带齐了。','nǐ hǎo ， wǒ jīn tiān yù yuē le qiān zhèng xù qiān ， gāng gāng sǎo mǎ xiǎn shì yù yuē hào shī xiào le ， wǒ suǒ yǒu bàn lǐ cái liào dōu dài qí le 。','Chào chị, hôm nay em đặt hẹn gia hạn visa, vừa quét mã thì báo số hẹn hết hiệu lực rồi, mà em đã mang đủ hết giấy tờ cần thiết.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_02','V1016','小徐',2,'失效的话是没办法直接办的哦，系统规定过期预约号作废，只能重新线上抢号排队，我们窗口不能直接受理。','shī xiào de huà shì méi bàn fǎ zhí jiē bàn de ó ， xì tǒng guī dìng guò qī yù yuē hào zuò fèi ， zhǐ néng chóng xīn xiàn shàng qiǎng hào pái duì ， wǒ men chuāng kǒu bù néng zhí jiē shòu lǐ 。','Hết hiệu lực rồi thì không thể xử lý trực tiếp được đâu nhé, hệ thống quy định số hẹn quá hạn sẽ bị hủy, chỉ có thể đặt lại số mới trên mạng thôi, quầy chúng tôi không thể tiếp nhận trực tiếp được.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_03','V1016','阮明',3,'啊？可是我下周就要离校去参加学术会议，真的没时间重新预约排队，能不能通融一下，帮我走个加急？','a ？ kě shì wǒ xià zhōu jiù yào lí xiào qù cān jiā xué shù huì yì ， zhēn de méi shí jiān chóng xīn yù yuē pái duì ， néng bù néng tōng róng yī xià ， bāng wǒ zǒu gè jiā jí ？','Hả? Nhưng tuần sau em phải rời trường đi dự hội nghị học thuật rồi, thật sự không có thời gian đặt hẹn xếp hàng lại nữa, chị có thể linh động giúp em làm nhanh được không ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_04','V1016','小徐',4,'我理解你着急，但我们加急通道是有严格标准的，只针对紧急就医、亲属病危这种突发特殊情况，普通出行、参会都不算加急范畴。','wǒ lǐ jiě nǐ zháo jí ， dàn wǒ men jiā jí tōng dào shì yǒu yán gé biāo zhǔn de ， zhǐ zhēn duì jǐn jí jiù yī 、 qīn shǔ bìng wēi zhè zhǒng tū fā tè shū qíng kuàng ， pǔ tōng chū xíng 、 cān huì dōu bù suàn jiā jí fàn chóu 。','Tôi hiểu em đang gấp, nhưng kênh xử lý nhanh của chúng tôi có tiêu chuẩn nghiêm ngặt, chỉ áp dụng cho các trường hợp khẩn cấp như cấp cứu y tế, người thân nguy kịch, còn đi lại bình thường hay dự hội nghị đều không thuộc diện ưu tiên.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_05','V1016','阮明',5,'不是普通出行！是学校安排的国际学术会议，特别重要，错过的话会影响我的学业成绩，邀请函我都带来了，您看一下。','bú shì pǔ tōng chū xíng ！ shì xué xiào ān pái de guó jì xué shù huì yì ， tè bié zhòng yào ， cuò guò de huà huì yǐng xiǎng wǒ de xué yè chéng jì ， yāo qǐng hán wǒ dōu dài lái le ， nín kàn yī xià 。','Không phải đi lại bình thường đâu ạ! Đây là hội nghị học thuật quốc tế do trường sắp xếp, rất quan trọng, nếu lỡ mất sẽ ảnh hưởng đến kết quả học tập của em, em mang cả thư mời đến rồi, chị xem giúp em ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_06','V1016','小徐',6,'行，那我帮你问问主管，看能不能特殊报备，你先在这边稍等，别走开。','xíng ， nà wǒ bāng nǐ wèn wèn zhǔ guǎn ， kàn néng bù néng tè shū bào bèi ， nǐ xiān zài zhè biān shāo děng ， bié zǒu kāi 。','Được rồi, để tôi hỏi giúp em quản lý xem có thể báo cáo trường hợp đặc biệt không, em cứ đợi ở đây một lát, đừng đi đâu nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_07','V1016','阮明',7,'麻烦您多帮我说说情！我真的提前准备了很久，没想到预约号会突然失效，实在耽误不起时间。','má fán nín duō bāng wǒ shuō shuō qíng ！ wǒ zhēn de tí qián zhǔn bèi le hěn jiǔ ， méi xiǎng dào yù yuē hào huì tū rán shī xiào ， shí zài dān wù bù qǐ shí jiān 。','Phiền chị nói giúp em nhiều nhé! Em thật sự đã chuẩn bị từ lâu rồi, không ngờ số hẹn lại đột nhiên hết hiệu lực, thực sự không thể chậm trễ thêm được nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_08','V1016','小徐',8,'我刚问过主管了，还是不行。不符合加急规定，系统录入不了信息，今天无论如何都办不了。','wǒ gāng wèn guò zhǔ guǎn le ， hái shì bù xíng 。 bù fú hé jiā jí guī dìng ， xì tǒng lù rù bù liǎo xìn xī ， jīn tiān wú lùn rú hé dōu bàn bù liǎo 。','Tôi vừa hỏi quản lý rồi, vẫn không được. Không đúng quy định ưu tiên, hệ thống không nhập được thông tin, hôm nay dù thế nào cũng không xử lý được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_09','V1016','阮明',9,'这样啊……那现在还有别的办法吗？','zhè yàng a …… nà xiàn zài hái yǒu bié de bàn fǎ ma ？','Vậy à... vậy giờ còn cách nào khác không ạ?','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1016_10','V1016','小徐',10,'没有别的捷径，只能明天早点自己抢新的预约号，按正常流程办理。','méi yǒu bié de jié jìng ， zhǐ néng míng tiān zǎo diǎn zì jǐ qiǎng xīn de yù yuē hào ， àn zhèng cháng liú chéng bàn lǐ 。','Không còn cách nào khác đâu, chỉ có thể ngày mai dậy sớm tự đặt số hẹn mới, làm theo quy trình bình thường thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1017','SKC1','诈骗来电谎称家人重病要求汇款，冷静核实后联系学院反诈老师',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1017','SIT1017','P1','suon_se','ban_chinh_thuc',NULL,'国内高校会定期开展留学生反诈宣讲，遭遇疑似诈骗可直接联系国际学院辅导员，同步上报公安反诈平台。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_01','V1017','阮明',1,'郑老师，我刚刚接到一个特别奇怪的陌生电话，心里特别慌。','zhèng lǎo shī ， wǒ gāng gāng jiē dào yí gè tè bié qí guài de mò shēng diàn huà ， xīn lǐ tè bié huāng 。','Cô Trịnh ơi, em vừa nhận được một cuộc điện thoại lạ rất kỳ lạ, trong lòng hoảng quá.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_02','V1017','郑老师',2,'别急，慢慢说，怎么了？','bié jí ， màn màn shuō ， zěn me le ？','Đừng vội, từ từ nói xem, chuyện gì vậy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_03','V1017','阮明',3,'对方说我妈妈突发重病住院，情况很危急，让我马上转账医药费过去，不然就来不及了。','duì fāng shuō wǒ mā mā tū fā zhòng bìng zhù yuàn ， qíng kuàng hěn wēi jí ， ràng wǒ mǎ shàng zhuǎn zhàng yī yào fèi guò qù ， bù rán jiù lái bù jí le 。','Đối phương nói mẹ em đột nhiên bị bệnh nặng phải nhập viện, tình hình rất nguy cấp, bảo em chuyển tiền viện phí ngay không thì không kịp nữa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_04','V1017','郑老师',4,'千万别转钱！第一时间联系家里人核实了吗？打电话或者视频都可以。','qiān wàn bié zhuǎn qián ！ dì yī shí jiān lián xì jiā lǐ rén hé shí le ma ？ dǎ diàn huà huò zhě shì pín dōu kě yǐ 。','Tuyệt đối đừng chuyển tiền! Em đã liên lạc với người nhà để xác minh ngay chưa? Gọi điện hay gọi video đều được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_05','V1017','阮明',5,'我当时差点就信了，赶紧挂了电话打视频给我妈妈，她好好的，身体一点问题都没有，完全是骗人的！','wǒ dāng shí chà diǎn jiù xìn le ， gǎn jǐn guà le diàn huà dǎ shì pín gěi wǒ mā mā ， tā hǎo hǎo de ， shēn tǐ yì diǎn wèn tí dōu méi yǒu ， wán quán shì piàn rén de ！','Lúc đó em suýt tin luôn, em vội cúp máy rồi gọi video cho mẹ, mẹ em vẫn khỏe re, chẳng có vấn đề gì cả, đúng là lừa đảo!',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_06','V1017','郑老师',6,'那就好，这是典型的跨境亲属诈骗，专门针对海外、外籍留学生，是很常见的诈骗手段。','nà jiù hǎo ， zhè shì diǎn xíng de kuà jìng qīn shǔ zhà piàn ， zhuān mén zhēn duì hǎi wài 、 wài jí liú xué shēng ， shì hěn cháng jiàn de zhà piàn shǒu duàn 。','Vậy thì tốt rồi, đây là kiểu lừa đảo người thân xuyên biên giới điển hình, chuyên nhắm vào du học sinh nước ngoài, là chiêu lừa rất phổ biến.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_07','V1017','阮明',7,'太吓人了！骗子居然知道我的名字、还有我家里的大致情况，信息特别准，我一开始完全没怀疑。','tài xià rén le ！ piàn zi jū rán zhī dào wǒ de míng zì 、 hái yǒu wǒ jiā lǐ de dà zhì qíng kuàng ， xìn xī tè bié zhǔn ， wǒ yī kāi shǐ wán quán méi huái yí 。','Sợ thật đấy! Kẻ lừa đảo còn biết tên em, biết cả sơ sơ tình hình gia đình em, thông tin chuẩn xác đến mức em lúc đầu chẳng nghi ngờ gì cả.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_08','V1017','郑老师',8,'正常的，这类骗子都会提前搜集学生公开信息。你把刚才的来电号码发给我。','zhèng cháng de ， zhè lèi piàn zi dōu huì tí qián sōu jí xué shēng gōng kāi xìn xī 。 nǐ bǎ gāng cái de lái diàn hào mǎ fā gěi wǒ 。','Bình thường thôi, loại lừa đảo này đều thu thập trước thông tin công khai của sinh viên. Em gửi số điện thoại vừa gọi đến cho cô.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_09','V1017','阮明',9,'好，我马上截图转发给您。','hǎo ， wǒ mǎ shàng jié tú zhuǎn fā gěi nín 。','Dạ, em chụp màn hình gửi cho cô ngay đây ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_10','V1017','郑老师',10,'我会统一上报给反诈中心，录入拦截名单，避免更多人被骗。你记住，以后但凡有人催你立刻转账、说家里出事的，一律先核实，绝不轻信。','wǒ huì tǒng yī shàng bào gěi fǎn zhà zhōng xīn ， lù rù lán jié míng dān ， bì miǎn gèng duō rén bèi piàn 。 nǐ jì zhù ， yǐ hòu dàn fán yǒu rén cuī nǐ lì kè zhuǎn zhàng 、 shuō jiā lǐ chū shì de ， yī lǜ xiān hé shí ， jué bù qīng xìn 。','Cô sẽ báo cáo lên trung tâm chống lừa đảo, đưa vào danh sách chặn, để tránh nhiều người khác bị lừa. Em nhớ nhé, sau này hễ ai giục em chuyển tiền gấp, nói nhà có chuyện, thì phải xác minh trước, tuyệt đối đừng tin ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1017_11','V1017','阮明',11,'我记住了！以后遇到这种事，我第一时间找您咨询，绝对不冲动转账。','wǒ jì zhù le ！ yǐ hòu yù dào zhè zhǒng shì ， wǒ dì yī shí jiān zhǎo nín zī xún ， jué duì bù chōng dòng zhuǎn zhàng 。','Em nhớ rồi ạ! Sau này gặp chuyện như vậy, em sẽ hỏi cô ngay, tuyệt đối không chuyển tiền theo cảm tính.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT1018','SKC1','校园学习账号被盗用登录，联系学校信息中心紧急冻结账号',NULL,'B2') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V1018','SIT1018','P1','twist','ban_chinh_thuc',NULL,'国内高校校园账号绑定学籍、选课、图书馆借阅权限，被盗用可能泄露个人学籍信息，必须线下核验身份永久冻结。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_01','V1018','阮明',1,'您好，麻烦帮我查一下我的校园学习账号，好像被盗用了！系统提示凌晨在外地登录，不是我本人操作。','nín hǎo ， má fán bāng wǒ chá yī xià wǒ de xiào yuán xué xí zhàng hào ， hǎo xiàng bèi dào yòng le ！ xì tǒng tí shì líng chén zài wài dì dēng lù ， bú shì wǒ běn rén cāo zuò 。','Chào anh, phiền anh kiểm tra giúp em tài khoản học tập của trường, hình như bị đánh cắp rồi! Hệ thống báo có người đăng nhập lúc nửa đêm ở nơi khác, không phải em thao tác.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_02','V1018','小高',2,'没问题，报一下你的学号和实名姓名，我先调取登录记录核对情况。','méi wèn tí ， bào yī xià nǐ de xué hào hé shí míng xìng míng ， wǒ xiān diào qǔ dēng lù jì lù hé duì qíng kuàng 。','Không vấn đề gì, em cho anh xin mã số sinh viên và họ tên thật, anh kiểm tra lịch sử đăng nhập trước đã.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_03','V1018','阮明',3,'学号20230418，名字是阮明。我现在特别担心，账号里有我的选课信息和个人资料，怕被别人乱用。','xué hào 20230418， míng zì shì ruǎn míng 。 wǒ xiàn zài tè bié dān xīn ， zhàng hào lǐ yǒu wǒ de xuǎn kè xìn xī hé gè rén zī liào ， pà bèi bié rén luàn yòng 。','Mã số sinh viên là 20230418, tên là Nguyễn Minh. Em đang lo lắm, trong tài khoản có thông tin đăng ký môn học và tài liệu cá nhân của em, sợ bị người khác lợi dụng lung tung.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_04','V1018','小高',4,'查到了，确实有一条异地陌生登录记录。想要彻底锁定账号、杜绝被盗用，需要你本人带学生证来机房线下办理手续。','chá dào le ， què shí yǒu yī tiáo yì dì mò shēng dēng lù jì lù 。 xiǎng yào chè dǐ suǒ dìng zhàng hào 、 dù jué bèi dào yòng ， xū yào nǐ běn rén dài xué shēng zhèng lái jī fáng xiàn xià bàn lǐ shǒu xù 。','Tìm ra rồi, đúng là có một lượt đăng nhập lạ từ nơi khác. Muốn khóa hẳn tài khoản, ngăn chặn triệt để việc bị chiếm dụng, em cần mang thẻ sinh viên đến phòng máy làm thủ tục trực tiếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_05','V1018','阮明',5,'啊？可是我现在正在教学楼上课，根本走不开，能不能先线上临时冻结一下？我下课马上过去办正式手续。','a ？ kě shì wǒ xiàn zài zhèng zài jiào xué lóu shàng kè ， gēn běn zǒu bù kāi ， néng bù néng xiān xiàn shàng lín shí dòng jié yī xià ？ wǒ xià kè mǎ shàng guò qù bàn zhèng shì shǒu xù 。','Hả? Nhưng giờ em đang học trên giảng đường, không thể rời đi được, anh có thể khóa tạm thời online trước được không ạ? Tan học em chạy qua làm thủ tục chính thức ngay.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_06','V1018','小高',6,'线上只能做临时限制，有效期只有两个小时，时间一到就会自动解除，没办法永久锁定。','xiàn shàng zhǐ néng zuò lín shí xiàn zhì ， yǒu xiào qī zhǐ yǒu liǎng gè xiǎo shí ， shí jiān yī dào jiù huì zì dòng jiě chú ， méi bàn fǎ yǒng jiǔ suǒ dìng 。','Online chỉ có thể giới hạn tạm thời thôi, thời hạn chỉ có hai tiếng, hết giờ là tự động mở lại, không thể khóa vĩnh viễn được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L1018_07','V1018','阮明',7,'两小时……应该够我下课赶过去了。麻烦您现在先帮我锁上，别让别人继续登录操作。','liǎng xiǎo shí …… yīng gāi gòu wǒ xià kè gǎn guò qù le 。 má fán nín xiàn zài xiān bāng wǒ suǒ shàng ， bié ràng bié rén jì xù dēng lù cāo zuò 。','Hai tiếng... chắc đủ để em tan học chạy qua kịp. Phiền anh khóa tạm giúp em ngay bây giờ, đừng để người khác tiếp tục đăng nhập thao tác.',NULL) ON CONFLICT DO NOTHING;
